from questions import M,F,part

# Original 2027-format mock exam. Part A has 29 questions; Part B has 13.
M('E01',1,'Conjugate limit',r'$\lim_{x\to4}(\sqrt{x+5}-3)/(x-4)$를 구하라.',r'Evaluate $\lim_{x\to4}(\sqrt{x+5}-3)/(x-4)$.',['1/6','1/3','3','0'],r'켤레식으로 유리화하면 $1/(\sqrt{x+5}+3)$이므로 극한은 $1/6$이다.',r'Rationalize to get $1/(\sqrt{x+5}+3)$.','limit((sqrt(x+5)-3)/(x-4),x,4)')
M('E02',2,'Basic derivatives',r'$f(x)=e^x+x^{-2}$일 때 $f\prime(1)$은?',r'For $f(x)=e^x+x^{-2}$, find $f\prime(1)$.',['exp(1)-2','exp(1)+2','exp(1)-1','exp(1)'],r'$f\prime=e^x-2x^{-3}$이다.',r'Apply the exponential and power rules.','diff(exp(x)+x**(-2),x).subs(x,1)')
M('E03',3,'Implicit slope',r'$xy+y^2=6$ 위의 점 $(1,2)$에서 접선 기울기는?',r'Find the tangent slope at $(1,2)$ on $xy+y^2=6$.',['-2/5','-1/2','-5/2','2/5'],r'$y+(x+2y)y\prime=0$이므로 $y\prime=-2/5$이다.',r'Differentiate implicitly and substitute the point.','(-y/(x+2*y)).subs({x:1,y:2})')
M('E04',4,'Rate interpretation',r'$T(t)$는 섭씨 온도이고 $t$는 분이다. $T\prime(5)=3.2$는 무엇을 뜻하는가?',r'$T(t)$ is degrees Celsius and $t$ is minutes. What does $T\prime(5)=3.2$ mean?',[('$5$분일 때 온도가 분당 $3.2$도씩 오른다','At minute $5$, temperature rises at $3.2$ degrees per minute'),('$5$분 동안 $3.2$도 올랐다','It rose $3.2$ degrees over five minutes'),('$5$분일 때 온도가 $3.2$도이다','The temperature at minute $5$ is $3.2$ degrees'),('온도 증가율이 분당 $3.2$씩 증가한다','The temperature rate increases by $3.2$ each minute')],r'일차 도함수는 그 순간의 온도 변화율이다.',r'The first derivative gives instantaneous temperature rate.')
M('E05',5,'MVT with logarithms',r'$f(x)=\ln x$의 $[1,e^2]$에서 평균값정리를 만족하는 $c$는?',r'For $f(x)=\ln x$ on $[1,e^2]$, find the MVT point $c$.',['(exp(2)-1)/2','exp(1)','2/(exp(2)-1)','(exp(2)+1)/2'],r'$1/c=2/(e^2-1)$을 풀면 $c=(e^2-1)/2$이다. 이 함수는 필요한 구간에서 연속이고 미분가능하다.',r'Set the derivative $1/c$ equal to the average rate $2/(e^2-1)$.','(exp(2)-1)/2')
M('E06',6,'Symmetric integration',r'$\int_{-1}^1(3x^2+2x)\,dx$는?',r'Evaluate $\int_{-1}^1(3x^2+2x)\,dx$.',['2','0','4','6'],r'홀함수 부분은 상쇄되고 짝함수 부분의 적분은 $2$이다.',r'The odd term integrates to zero and the even term contributes $2$.','integrate(3*x**2+2*x,(x,-1,1))')
M('E07',7,'Exponential solution',r'$y\prime=2y$, $y(0)=5$일 때 $y(1)$은?',r'If $y\prime=2y$ and $y(0)=5$, find $y(1)$.',['5*exp(2)','10','5*exp(1)','7'],r'$y=5e^{2x}$이므로 값은 $5e^2$이다.',r'Solve the exponential initial-value problem.','(5*exp(2*x)).subs(x,1)')
M('E08',8,'Area from intersections',r'$y=2x-x^2$와 $x$축으로 둘러싸인 넓이는?',r'Find the area bounded by $y=2x-x^2$ and the $x$-axis.',['4/3','2/3','8/3','2'],r'영점 $0,2$ 사이에서 함수는 양수이므로 적분은 $4/3$이다.',r'Integrate the positive function from $0$ to $2$.','integrate(2*x-x**2,(x,0,2))')
M('E09',1,'Infinite limit',r'$\lim_{x\to2}1/(x-2)^2$는?',r'Evaluate $\lim_{x\to2}1/(x-2)^2$.',['oo','-oo','0','1'],r'양쪽에서 분모가 양수로 0에 가까워져 양의 무한대로 발산한다.',r'The denominator tends to zero through positive values from both sides.','limit(1/(x-2)**2,x,2)')
M('E10',2,'Table derivative',r'$x=1,2,3$에서 $f(x)=5,8,15$이다. $x=1,3$으로 $f\prime(2)$를 추정하면?',r'At $x=1,2,3$, $f(x)=5,8,15$. Estimate $f\prime(2)$ using $x=1,3$.',['5','7','3','10'],r'$(15-5)/(3-1)=5$이다.',r'Take the centered secant slope.','Rational(15-5,3-1)')
M('E11',3,'Arcsine chain rule',r'$f(x)=\arcsin(x/2)$일 때 $f\prime(1)$은?',r'For $f(x)=\arcsin(x/2)$, find $f\prime(1)$.',['1/sqrt(3)','2/sqrt(3)','1/2','sqrt(3)'],r'$f\prime=(1/2)/\sqrt{1-x^2/4}$에 대입한다.',r'Include the inner derivative $1/2$.','diff(asin(x/2),x).subs(x,1)')
M('E12',4,'Indeterminate form',r'$\lim_{x\to0}\ln(1+3x)/\sin(2x)$는?',r'Evaluate $\lim_{x\to0}\ln(1+3x)/\sin(2x)$.',['3/2','2/3','3','0'],r'$0/0$형에서 로피탈의 정리를 적용하면 $3/2$이다.',r'Apply L Hospital rule after checking the $0/0$ form.','limit(log(1+3*x)/sin(2*x),x,0)')
M('E13',5,'Derivative graph concavity',r'그림은 $f\prime$의 그래프이다. $f$가 위로 오목한 열린 구간은?',r'The graph shows $f\prime$. On which open intervals is $f$ concave up?',[('$(0,1)$과 $(3,4)$','$(0,1)$ and $(3,4)$'),('$(1,3)$','$(1,3)$'),('$(0,2)$','$(0,2)$'),('$(2,4)$','$(2,4)$')],r'$f\prime$가 증가하는 두 구간에서 $f^{\prime\prime}>0$이다.',r'Concavity is positive where the first derivative increases.' ,figure='derivative')
M('E14',6,'Riemann notation',r'$\lim_{n\to\infty}\sum_{i=1}^n(2/n)(1+2i/n)^2$는?',r'Evaluate $\lim_{n\to\infty}\sum_{i=1}^n(2/n)(1+2i/n)^2$.',['26/3','8/3','9','13/3'],r'구간 $[1,3]$에서 $x^2$의 적분이므로 $26/3$이다.',r'This is $\int_1^3x^2\,dx$.','integrate(x**2,(x,1,3))')
M('E15',7,'Lost equilibrium',r'$y\prime=x(y+4)$를 변수분리하며 $y+4$로 나누었다. 따로 확인해야 하는 상수해는?',r'When separating $y\prime=x(y+4)$, one divides by $y+4$. Which constant solution must be checked separately?',['-4','4','0','-x'],r'$y=-4$는 양변을 0으로 만들고 나눗셈 과정에서 제외되었다.',r'The constant $-4$ satisfies the original equation but is excluded by division.','solve(y+4,y)[0]')
M('E16',8,'Trigonometric average',r'$\sin x$의 $[0,\pi]$에서 평균값은?',r'Find the average value of $\sin x$ on $[0,\pi]$.',['2/pi','2','1','pi/2'],r'적분 $2$를 구간 길이 $\pi$로 나눈다.',r'Divide the integral $2$ by the interval length $\pi$.','integrate(sin(x),(x,0,pi))/pi')
M('E17',1,'Existence argument',r'$p(x)=x^3+2x-1$이다. $(0,1)$에 영점이 있다는 올바른 근거는?',r'Which correctly justifies a zero of $p(x)=x^3+2x-1$ in $(0,1)$?',[('연속이고 $p(0)=-1<0<2=p(1)$이므로 중간값정리','Continuity and $p(0)=-1<0<2=p(1)$ allow IVT'),('모든 삼차식의 영점은 $(0,1)$에 있다','Every cubic has a zero in $(0,1)$'),('끝점의 부호만 반대이면 연속성은 필요 없다','Opposite endpoint signs suffice without continuity'),('$p(0)+p(1)>0$이기 때문이다','Because $p(0)+p(1)>0$')],r'다항함수의 연속성과 목표값을 사이에 두는 끝점 값이 모두 필요하다.',r'Use polynomial continuity and endpoint values on opposite sides of zero.')
M('E18',2,'Product and trig',r'$f(x)=x\sin x$일 때 $f\prime(\pi)$는?',r'For $f(x)=x\sin x$, find $f\prime(\pi)$.',['-pi','pi','0','-1'],r'$f\prime=\sin x+x\cos x$이므로 $-\pi$이다.',r'Apply the product rule before substituting.','diff(x*sin(x),x).subs(x,pi)')
M('E19',4,'Cylindrical rate',r'반지름이 고정된 $2$ m 원통에서 물 높이가 $3$ m/min씩 증가한다. 부피 변화율은 몇 m$^3$/min인가?',r'Water depth rises at $3$ m/min in a cylinder of fixed radius $2$ m. Find the volume rate in m$^3$/min.',['12*pi','6*pi','4*pi','24*pi'],r'$V=4\pi h$이므로 $V\prime=4\pi\cdot3=12\pi$이다.',r'Multiply the fixed cross-sectional area by the height rate.','pi*2**2*3')
M('E20',5,'Candidate test',r'$f(x)=x^4-4x^2$의 $[-2,2]$에서 절대최솟값은?',r'Find the absolute minimum of $f(x)=x^4-4x^2$ on $[-2,2]$.',['-4','0','-8','4'],r'후보 $-2,-\sqrt2,0,\sqrt2,2$의 값을 비교하면 최소는 $-4$이다.',r'Compare endpoints and critical numbers $0,\pm\sqrt2$.','min([(x**4-4*x**2).subs(x,a) for a in [-2,-sqrt(2),0,sqrt(2),2]])')
M('E21',6,'Inverse trig integral',r'$\int_0^1 1/(1+x^2)\,dx$는?',r'Evaluate $\int_0^1 1/(1+x^2)\,dx$.',['pi/4','pi/2','log(2)','1/2'],r'원시함수는 $\arctan x$이다.',r'Use the arctangent antiderivative.','integrate(1/(1+x**2),(x,0,1))')
M('E22',8,'Rotation about y axis',r'$x=\sqrt y$, $y$축, $y=4$가 둘러싼 영역을 $y$축 둘레로 회전한 부피는?',r'Rotate the region bounded by $x=\sqrt y$, the $y$-axis, and $y=4$ about the $y$-axis. Find the volume.',['8*pi','16*pi','4*pi','32*pi/3'],r'가로 원판을 쓰면 $V=\pi\int_0^4y\,dy=8\pi$이다.',r'Use horizontal disks with radius $\sqrt y$.','pi*integrate(y,(y,0,4))')
M('E23',1,'Trigonometric limit',r'$\lim_{x\to0}\sin(5x)/(3x)$는?',r'Evaluate $\lim_{x\to0}\sin(5x)/(3x)$.',['5/3','3/5','0','1'],r'$5/3$을 밖으로 빼면 기본 삼각극한이 남는다.',r'Factor out $5/3$ and use the standard sine limit.','limit(sin(5*x)/(3*x),x,0)')
M('E24',2,'Piecewise differentiability',r'$x<1$에서는 $f(x)=ax+b$, $x\ge1$에서는 $f(x)=x^2$이다. $x=1$에서 미분가능할 때 $b$는?',r'Let $f(x)=ax+b$ for $x<1$ and $f(x)=x^2$ for $x\ge1$. If $f$ is differentiable at $1$, find $b$.',['-1','1','2','0'],r'연속성으로 $a+b=1$, 기울기 일치로 $a=2$이다. 따라서 $b=-1$이다.',r'Continuity requires $a+b=1$ and matching slopes require $a=2$.','1-diff(x**2,x).subs(x,1)')
M('E25',5,'Implicit concavity',r'$y=\sqrt{9-x^2}$의 $-3<x<3$에서 오목성은?',r'What is the concavity of $y=\sqrt{9-x^2}$ on $-3<x<3$?',[('구간 전체에서 아래로 오목하다','Concave down throughout'),('구간 전체에서 위로 오목하다','Concave up throughout'),('$x=0$에서 오목성이 바뀐다','Concavity changes at zero'),('선형이다','Linear')],r'$y^{\prime\prime}=-9/(9-x^2)^{3/2}<0$이다.',r'The second derivative is $-9/(9-x^2)^{3/2}<0$.')
M('E26',6,'Completing the square',r'$1/(x^2-2x+5)$의 한 원시함수는?',r'Which is an antiderivative of $1/(x^2-2x+5)$?',['atan((x-1)/2)/2','atan(x-1)','log(x**2-2*x+5)','2*atan((x-1)/2)'],r'분모를 $(x-1)^2+4$로 쓰면 $\frac12\arctan((x-1)/2)$이다. 미분해서 확인할 수 있다.',r'Complete the square and use the scaled arctangent form.','integrate(1/(x**2-2*x+5),x)')
M('E27',8,'Semicircular cross sections',r'$0\le x\le2$에서 단면이 지름 $2-x$인 반원이다. 부피는?',r'Cross sections are semicircles of diameter $2-x$ for $0\le x\le2$. Find the volume.',['pi/3','2*pi/3','4*pi/3','8/3'],r'단면 넓이는 $\pi(2-x)^2/8$이다. 적분하면 $\pi/3$이다.',r'The cross-sectional area is $\pi(2-x)^2/8$.','pi*integrate((2-x)**2,(x,0,2))/8')
M('E28',5,'First derivative test',r'$f\prime(x)=x^2(x+1)$이다. 극값에 대한 옳은 설명은?',r'If $f\prime(x)=x^2(x+1)$, which statement about local extrema is correct?',[('$x=-1$에서 극소이고 $x=0$에서는 극값이 없다','A local minimum at $-1$ and no extremum at $0$'),('두 점 모두 극소이다','Both points are minima'),('$x=0$에서만 극대이다','Only $0$ is a maximum'),('$x=-1$에서 극대이다','There is a maximum at $-1$')],r'$-1$에서 부호가 음에서 양으로 바뀌고 $0$에서는 양의 부호가 유지된다.',r'The derivative changes from negative to positive at $-1$ and stays positive across $0$.')
M('E29',6,'Two variable endpoints',r'$F(x)=\int_x^{2x}\cos(t^2)\,dt$일 때 $F\prime(0)$은?',r'If $F(x)=\int_x^{2x}\cos(t^2)\,dt$, find $F\prime(0)$.',['1','2','0','-1'],r'$F\prime(x)=2\cos(4x^2)-\cos(x^2)$이므로 $F\prime(0)=1$이다.',r'Apply FTC to both endpoints with their chain factors.','(2*cos(4*x**2)-cos(x**2)).subs(x,0)')

# Calculator-required Part B. Answer options are rounded to three decimals.
M('E30',1,'Numerical zero',r'$p(x)=x^3+x-4$의 $[1,2]$ 안의 영점을 세 자리 소수로 구하라.',r'Find the zero of $p(x)=x^3+x-4$ in $[1,2]$ to three decimal places.',['1.379','1.213','1.587','1.812'],r'연속성과 끝점 부호로 해가 있고 $p\prime=3x^2+1>0$이므로 유일하다. 수치적으로 $x=1.378796700\ldots$이다.',r'Continuity gives existence and a positive derivative gives uniqueness. Numerical solving gives $1.378796700\ldots$.','nroot(x**3+x-4,x,1,2)',True)
M('E31',2,'Numerical product derivative',r'$f(x)=x^2e^x$일 때 $f\prime(0.7)$을 구하라.',r'For $f(x)=x^2e^x$, find $f\prime(0.7)$.',['3.806','0.987','2.819','1.904'],r'$f\prime=e^x(x^2+2x)$를 계산하면 $3.805992617\ldots$이다.',r'Apply the product rule and evaluate $e^x(x^2+2x)$.','diff(x**2*exp(x),x).subs(x,Rational(7,10))',True)
M('E32',3,'Numerical inverse slope',r'$f(x)=x+e^x$, $g=f^{-1}$이다. $b=1.2+e^{1.2}$일 때 $g\prime(b)$는?',r'Let $f(x)=x+e^x$ and $g=f^{-1}$. If $b=1.2+e^{1.2}$, find $g\prime(b)$.',['0.231','0.301','0.432','4.320'],r'대응 입력은 $1.2$이다. $g\prime(b)=1/(1+e^{1.2})=0.231475216\ldots$이다.',r'Use the reciprocal of $f\prime(1.2)$, not of $f\prime(b)$.','1/(1+exp(Rational(6,5)))',True)
M('E33',4,'Acceleration value',r'$v(t)=\sin(t^2)+0.2t$ m/s이다. $t=1.4$에서 가속도는 몇 m/s$^2$인가?',r'If $v(t)=\sin(t^2)+0.2t$ m/s, find acceleration at $t=1.4$ in m/s$^2$.',['-0.862','1.205','-0.379','0.862'],r'$a(t)=2t\cos(t^2)+0.2$이므로 $a(1.4)=-0.862464941\ldots$이다.',r'Differentiate velocity before evaluating.','diff(sin(t**2)+t/5,t).subs(t,Rational(7,5))',True)
M('E34',5,'Numerical optimization',r'$f(x)=x^2+e^{-x}$가 $[0,2]$에서 절대최소를 갖는 $x$는?',r'Where does $f(x)=x^2+e^{-x}$ attain its absolute minimum on $[0,2]$?',['0.352','0.693','1.000','1.256'],r'$f\prime=2x-e^{-x}=0$의 해는 $0.351733711\ldots$이다. $f^{\prime\prime}=2+e^{-x}>0$이므로 구간에서 유일한 최소이다.',r'Solve $2x-e^{-x}=0$. The positive second derivative confirms the unique minimum.','nroot(2*x-exp(-x),x,0,1)',True)
M('E35',5,'Numerical maximum value',r'$f(x)=2\sin x-x^2/2$의 $[0,\pi]$에서 절대최댓값은?',r'Find the absolute maximum value of $f(x)=2\sin x-x^2/2$ on $[0,\pi]$.',['1.184','1.030','2.000','0.816'],r'$f\prime=2\cos x-x=0$에서 $x=1.029866529\ldots$이다. 끝점과 비교하면 최대 함숫값은 $1.184148003\ldots$이다.',r'The critical input is about $1.029866529$. Comparing with endpoints gives maximum value $1.184148003\ldots$.','(2*sin(x)-x**2/2).subs(x,nroot(2*cos(x)-x,x,0,2))',True)
M('E36',6,'Numerical definite integral',r'$\int_0^1e^{-x^2}\,dx$를 구하라.',r'Evaluate $\int_0^1e^{-x^2}\,dx$ numerically.',['0.747','0.632','0.842','1.128'],r'수치적분하면 $0.746824133\ldots$이다. $e^{-x^2}$의 초등 원시함수를 억지로 만들지 않는다.',r'Numerical integration gives $0.746824133\ldots$; no elementary antiderivative is needed.','nint(exp(-x**2),x,0,1)',True)
M('E37',6,'Accumulation derivative value',r'$F(x)=\int_0^{\ln x}e^{-t^2}\,dt$일 때 $F\prime(2)$는?',r'For $F(x)=\int_0^{\ln x}e^{-t^2}\,dt$, find $F\prime(2)$.',['0.309','0.619','0.347','0.240'],r'$F\prime(x)=e^{-(\ln x)^2}/x$이므로 $0.309251569\ldots$이다.',r'Apply FTC and multiply by the derivative of the logarithmic endpoint.','exp(-log(2)**2)/2',True)
M('E38',6,'Decimal trapezoids',r'표의 세 구간에 사다리꼴합을 적용해 $\int_0^2 f(x)\,dx$를 추정하라.',r'Use three trapezoids from the table to estimate $\int_0^2f(x)\,dx$.',['3.625','3.450','3.800','4.100'],r'$0.5(1+1.6)/2+1(1.6+2.1)/2+0.5(2.1+2.4)/2=3.625$이다.',r'Use the separate widths $0.5,1,0.5$.','Rational(1,2)*Rational(26,10)/2+Rational(37,10)/2+Rational(1,2)*Rational(45,10)/2',True,table={'headers':['x','f(x)'],'rows':[['0','1'],['0.5','1.6'],['1.5','2.1'],['2','2.4']]})
M('E39',7,'Time to a target',r'$y\prime=0.4(10-y)$, $y(0)=2$이다. 처음 $y=8$이 되는 시간은?',r'If $y\prime=0.4(10-y)$ and $y(0)=2$, when does $y$ first reach $8$?',['3.466','1.733','2.500','5.198'],r'$y=10-8e^{-0.4t}$에서 $e^{-0.4t}=1/4$이므로 $t=(\ln4)/0.4$이다.',r'Solve the initial-value model, then solve the target equation.','log(4)/Rational(2,5)',True)
M('E40',8,'Area with a numerical intersection',r'$y=e^{-x}$, $y=x/2$, $y$축으로 둘러싸인 넓이는?',r'Find the area enclosed by $y=e^{-x}$, $y=x/2$, and the $y$-axis.',['0.392','0.853','0.574','0.608'],r'교점은 $a=0.852605502\ldots$이다. 넓이는 $\int_0^a(e^{-x}-x/2)\,dx=0.391963213\ldots$이다.',r'Find the intersection numerically, then integrate top minus bottom.','nint(exp(-x)-x/2,x,0,nroot(exp(-x)-x/2,x,0,2))',True)
M('E41',8,'Numerical distance',r'$v(t)=\cos t-0.2$ m/s인 입자의 $[0,4]$에서 총 이동거리는 몇 m인가?',r'For $v(t)=\cos t-0.2$ m/s, find total distance on $[0,4]$ in meters.',['2.969','1.557','0.757','3.517'],r'부호는 $c=\arccos(0.2)$에서 바뀐다. $\int_0^c v\,dt-\int_c^4v\,dt=2.968618927\ldots$이다.',r'Split the absolute-velocity integral at $c=\arccos(0.2)$.','2*(sin(acos(Rational(1,5)))-acos(Rational(1,5))/5)-(sin(4)-Rational(4,5))',True)
M('E42',4,'Temperature rate',r'$T(t)=20+80e^{-0.3t}$일 때 $T\prime(4)$는?',r'If $T(t)=20+80e^{-0.3t}$, find $T\prime(4)$.',['-7.229','-24.096','7.229','44.096'],r'$T\prime=-24e^{-0.3t}$이므로 값은 $-7.228661086\ldots$이다.',r'Include the inner exponential factor $-0.3$.','diff(20+80*exp(-3*t/10),t).subs(t,4)',True)

# Six original free-response questions, each with an instructional 9-point rubric.
F('EF01',8,'Calculator accumulation',r'탱크에 처음 $40$ L의 물이 있다. $0\le t\le4$분에서 유입률은 $R(t)=12+3\sin(t^2/4)$ L/min, 유출률은 $D(t)=8+t$ L/min이다.',r'A tank initially contains $40$ liters. For $0\le t\le4$ minutes, inflow is $R(t)=12+3\sin(t^2/4)$ L/min and outflow is $D(t)=8+t$ L/min.',[
part(r'$t=4$에서 물의 양을 소수 셋째 자리까지 구하라.',r'Find the volume at $t=4$ to three decimal places.',r'$W(4)=40+\int_0^4(4-t+3\sin(t^2/4))\,dt=52.828658936\ldots$ L이다. 반올림하면 $52.829$ L이다.',r'The volume is $40+\int_0^4(4-t+3\sin(t^2/4))\,dt=52.828658936\ldots$, or $52.829$ liters.',3,'순변화율 적분 1점; 초기량 40 더하기 1점; 수치와 L 단위 1점','Net-rate integral 1; initial amount 1; number and liters 1','40+nint(4-t+3*sin(t**2/4),t,0,4)','52.8286589360625'),
part(r'$[0,4]$에서 물의 양이 최대가 되는 시각을 근거와 함께 구하라.',r'Justify the time when water volume is greatest on $[0,4]$.',r'$W\prime=4-t+3\sin(t^2/4)$이다. $(3,4)$의 유일한 영점은 $t=3.616504044\ldots$분이다. 처음부터 이 점까지 순변화율이 양수이며 이후 음수이므로 $t\approx3.617$분에서 최대이다.',r'The net rate $4-t+3\sin(t^2/4)$ has its unique zero in $(3,4)$ at $3.616504044\ldots$. Its change from positive to negative gives the maximum at about $3.617$ minutes.',3,'도함수인 순변화율 1점; 영점 수치 1점; 부호와 끝점 근거 1점','Net derivative 1; numerical root 1; signs and endpoint reasoning 1','nroot(4-t+3*sin(t**2/4),t,3,4)','3.61650404395937'),
part(r'$t=2$에서 물의 양의 증가율이 커지고 있는지 설명하라.',r'At $t=2$, is the water-volume rate increasing? Justify.',r'$W^{\prime\prime}(2)=3\cos1-1\approx0.621>0$이므로 순유입률이 증가한다. 물의 양의 증가와 증가율의 증가는 서로 다른 질문이다.',r'The second derivative is $W^{\prime\prime}(2)=3\cos1-1\approx0.621>0$, so the net-volume rate is increasing.',3,'둘째 도함수 식 1점; 값과 양의 부호 1점; 증가율 해석 1점','Second derivative 1; positive evaluated sign 1; rate interpretation 1','3*cos(1)-1','0.620906917604419')],calc=True)

F('EF02',6,'Calculator integral model',r'$f(x)=e^{-x^2}+x/4$이고 $F(x)=\int_0^x f(t)\,dt$이다. $0\le x\le2$이다.',r'Let $f(x)=e^{-x^2}+x/4$ and $F(x)=\int_0^x f(t)\,dt$ for $0\le x\le2$.',[
part(r'$F(2)$와 $f$의 구간 평균값을 구하라.',r'Find $F(2)$ and the average value of $f$ on the interval.',r'$F(2)=\int_0^2(e^{-x^2}+x/4)\,dx=1.382081391\ldots$이다. 평균은 $F(2)/2=0.691040695\ldots$이다.',r'The numerical integral is $F(2)=1.382081391\ldots$. The average is $F(2)/2=0.691040695\ldots$.',3,'정적분 식 1점; F 수치 1점; 평균을 위한 나눗셈 1점','Integral setup 1; numerical F 1; divide for average 1','nint(exp(-x**2)+x/4,x,0,2)','1.38208139076242'),
part(r'$f$의 절대최댓값을 구하고 후보 비교를 제시하라.',r'Find the absolute maximum value of $f$ and show candidate comparisons.',r'임계수는 $0.127033555\ldots$, $1.595893206\ldots$이다. 양 끝점과 이 두 점의 함숫값은 각각 $1$, $0.518315639\ldots$, $1.015750377\ldots$, $0.477299345\ldots$이다. 따라서 최대는 $x\approx0.127$에서 $f\approx1.016$이다.',r'Critical inputs are $0.127033555\ldots$ and $1.595893206\ldots$. At $0,2$ and those critical inputs, values are $1$, $0.518315639\ldots$, $1.015750377\ldots$, and $0.477299345\ldots$. The maximum is about $1.016$ at $x\approx0.127$.',3,'두 내부 임계수 1점; 끝점 포함 비교 1점; 최대 함숫값 1점','Both interior critical numbers 1; endpoint comparison 1; maximum value 1','(exp(-x**2)+x/4).subs(x,nroot(-2*x*exp(-x**2)+Rational(1,4),x,0,Rational(1,2)))','1.01575037689122'),
part(r'$F$가 구간 전체에서 증가하는지 근거와 함께 설명하라.',r'Justify whether $F$ increases throughout the interval.',r'기본정리로 $F\prime=f$이다. $e^{-x^2}>0$이고 $x/4\ge0$이므로 구간에서 $F\prime>0$이다. 따라서 증가한다.',r'FTC gives $F\prime=f$. Since the exponential term is positive and $x/4\ge0$, the derivative is positive and $F$ increases throughout.',3,'기본정리 1점; 적분함수 양의 부호 1점; 증감 결론 1점','FTC 1; positive integrand argument 1; conclusion 1')],calc=True)

F('EF03',5,'Graph and accumulation',r'그림은 연속함수 $f$의 그래프이며 $G(x)=\int_0^x f(t)\,dt$이다. 정의역은 $[0,4]$이다.',r'The graph shows a continuous $f$ and $G(x)=\int_0^x f(t)\,dt$ on $[0,4]$.',[
part(r'$G(4)$와 $G\prime(2)$를 구하라.',r'Find $G(4)$ and $G\prime(2)$.',r'삼각형의 양의 넓이 $3$에서 음의 기여 $1$을 빼면 $G(4)=2$이다. $G\prime(2)=f(2)=1$이다.',r'The signed area is $3-1=2$, and FTC gives $G\prime(2)=1$.',3,'부호 있는 넓이 1점; G 값 1점; 도함수 값 1점','Signed-area calculation 1; G value 1; derivative value 1'),
part(r'$G$의 절대최대와 달성 위치를 근거와 함께 구하라.',r'Justify the absolute maximum of $G$ and its location.',r'$G\prime=f$는 $(0,3)$에서 양수, $(3,4)$에서 음수이다. 최대는 $x=3$에서 $G(3)=3$이다.',r'The derivative is positive before $3$ and negative after. The maximum is $G(3)=3$.',3,'도함수 연결 1점; 부호변화 1점; 위치와 값 1점','Derivative connection 1; sign change 1; location and value 1'),
part(r'$G$의 변곡점 입력을 모두 찾고, 왜 $x=1$도 포함되는지 설명하라.',r'Find all inflection inputs of $G$ and explain why $x=1$ is included.',r'$G\prime=f$는 $(0,1)$에서 증가하고 $(1,4)$에서 감소한다. 따라서 $G$는 $x=1$에서 위로 오목에서 아래로 오목으로 바뀐다. $x=3$에서는 $f$의 기울기가 $-1$에서 $-2$로 바뀌어도 둘 다 음수라 오목성은 바뀌지 않는다. 유일한 입력은 $1$이다.',r'Since $f$ increases before $1$ and decreases after, $G$ changes from concave up to down there. At $3$, the slopes of $f$ remain negative, so there is no concavity change. Only $1$ is an inflection input.',3,'f의 증감 읽기 1점; x=1의 오목성 변화 1점; 다른 후보 제외 1점','Monotonicity of f 1; concavity change at 1 1; exclude other candidates 1')],figure='accumulation')

F('EF04',7,'Separable initial value and tangent',r'$y\prime=2x(y+2)$이고 $y(0)=1$이다.',r'Consider $y\prime=2x(y+2)$ with $y(0)=1$.',[
part(r'초기점에서의 접선을 구하고 그 접선으로 $y(0.1)$을 추정하라.',r'Find the initial tangent line and use it to estimate $y(0.1)$.',r'초기 기울기는 $0$이므로 접선은 $y=1$, 근삿값도 $1$이다.',r'The initial slope is zero, so the tangent line is $y=1$ and the estimate is $1$.',3,'초기 기울기 1점; 접선식 1점; 근삿값 1점','Initial slope 1; tangent line 1; estimate 1'),
part(r'변수분리로 명시적 해를 구하라.',r'Find an explicit solution by separation.',r'$dy/(y+2)=2x\,dx$에서 $\ln|y+2|=x^2+C$이다. 초기조건으로 $y+2=3e^{x^2}$, 즉 $y=3e^{x^2}-2$이다.',r'Separate and integrate to get $y+2=Ce^{x^2}$. The initial condition gives $y=3e^{x^2}-2$.',3,'변수분리 1점; 적분 1점; 초기조건과 해 1점','Separation 1; integration 1; initial condition and solution 1','diff(3*exp(x**2)-2,x)-2*x*((3*exp(x**2)-2)+2)','0'),
part(r'(a)의 근사가 과대인지 과소인지 둘째 도함수로 설명하라.',r'Use the second derivative to decide whether the estimate in (a) is high or low.',r'$y^{\prime\prime}=2(y+2)+2xy\prime=2(y+2)(1+2x^2)>0$이다. 해가 위로 오목하므로 접선 근사 $1$은 과소근사이다.',r'The solution has $y+2>0$, so $y^{\prime\prime}=2(y+2)(1+2x^2)>0$. The tangent estimate is an underestimate.',3,'둘째 도함수 1점; 구간의 양의 부호 1점; 과소근사 결론 1점','Second derivative 1; positive sign on interval 1; underestimate conclusion 1')])

F('EF05',8,'Three dimensional cross sections',r'$R$은 $y=4-x^2$와 $x$축으로 둘러싸인 영역이다.',r'Let $R$ be the region bounded by $y=4-x^2$ and the $x$-axis.',[
part(r'$R$의 넓이를 구하라.',r'Find the area of $R$.',r'교점은 $x=\pm2$이고 넓이는 $\int_{-2}^2(4-x^2)\,dx=32/3$이다.',r'Intersections are $\pm2$; integrating the height gives $32/3$.',3,'교점 1점; 넓이 적분 1점; 결과 1점','Intersections 1; area integral 1; result 1','integrate(4-x**2,(x,-2,2))','32/3'),
part(r'$R$을 $x$축 둘레로 회전한 부피를 구하라.',r'Find the volume when $R$ revolves about the $x$-axis.',r'$V=\pi\int_{-2}^2(4-x^2)^2\,dx=512\pi/15$이다.',r'The disk integral is $512\pi/15$.',3,'반지름 1점; 제곱한 적분 1점; 부피 1점','Radius 1; squared-radius integral 1; volume 1','pi*integrate((4-x**2)**2,(x,-2,2))','512*pi/15'),
part(r'밑면이 $R$이고 $x$축에 수직인 단면이 정삼각형인 입체의 부피를 구하라.',r'A different solid has base $R$ and equilateral-triangle cross sections perpendicular to the $x$-axis. Find its volume.',r'한 변은 $4-x^2$이다. $V=(\sqrt3/4)\int_{-2}^2(4-x^2)^2\,dx=128\sqrt3/15$이다.',r'Each triangle has side $4-x^2$. Its area factor is $\sqrt3/4$, giving volume $128\sqrt3/15$.',3,'단면 변과 넓이 공식 1점; 적분 1점; 결과 1점','Side and triangle formula 1; integral 1; result 1','sqrt(3)*integrate((4-x**2)**2,(x,-2,2))/4','128*sqrt(3)/15')])

F('EF06',2,'Piecewise matching and theorem',r'$x<1$에서 $f(x)=ax+b$이고 $x\ge1$에서 $f(x)=x^2+1$이다. 함수가 $x=1$에서 미분가능하도록 정한다.',r'Let $f(x)=ax+b$ for $x<1$ and $f(x)=x^2+1$ for $x\ge1$. Choose parameters so that $f$ is differentiable at $1$.',[
part(r'$a,b$를 구하고 두 조건을 각각 제시하라.',r'Find $a,b$ and state both matching conditions.',r'연속성으로 $a+b=2$, 좌우 도함수 일치로 $a=2$이다. 따라서 $a=2,b=0$이다.',r'Continuity requires $a+b=2$ and matching one-sided derivatives require $a=2$. Thus $b=0$.',3,'연속성 조건 1점; 미분 조건 1점; 두 값 1점','Continuity condition 1; derivative condition 1; both parameters 1'),
part(r'$[0,2]$에서 평균값정리를 적용할 수 있는 이유를 쓰고, 정리를 만족하는 $c\in(0,2)$를 구하라.',r'Justify MVT on $[0,2]$ and find a point $c\in(0,2)$ satisfying it.',r'정한 함수는 $[0,2]$에서 연속이고 $(0,2)$에서 미분가능하다. 평균변화율은 $(5-0)/2=5/2$이다. 왼쪽 도함수는 $2$이며 오른쪽 $2c=5/2$를 풀면 $c=5/4$이다.',r'The matching conditions give continuity and differentiability. The average rate is $5/2$. The left derivative is $2$; on the right, $2c=5/2$ gives $c=5/4$.',3,'두 정리 가정 1점; 평균변화율 1점; 올바른 조각에서 c 1점','Both hypotheses 1; average rate 1; c in correct piece 1','Rational(5,2)/2','5/4'),
part(r'$f$의 $[0,2]$에서 평균값을 구하라.',r'Find the average value of $f$ on $[0,2]$.',r'$\frac12(\int_0^1 2x\,dx+\int_1^2(x^2+1)\,dx)=\frac12(1+10/3)=13/6$이다.',r'Split the integral at $1$ and divide by $2$ to obtain $13/6$.',3,'조각별 적분 1점; 적분 계산 1점; 구간 길이로 나눔 1점','Piecewise integral 1; evaluation 1; divide by interval length 1','(integrate(2*x,(x,0,1))+integrate(x**2+1,(x,1,2)))/2','13/6')])
